<?php
namespace App\Http\Controllers\Api\Budget; use App\Http\Controllers\Controller; use App\Models\Budget\BudgetReallocation; use App\Services\Budget\BudgetMonitoringService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class BudgetReallocationController extends Controller { public function index(){return response()->json(['success'=>true,'data'=>BudgetReallocation::with('fromLine','toLine')->latest()->get()]);} public function store(Request $r){$d=$r->validate(['project_id'=>'nullable|exists:projects,id','from_budget_line_id'=>'required|different:to_budget_line_id|exists:budget_lines,id','to_budget_line_id'=>'required|exists:budget_lines,id','amount'=>'required|numeric|min:0.01','reason'=>'required|string']);$from=\App\Models\Master\BudgetLine::findOrFail($d['from_budget_line_id']);$to=\App\Models\Master\BudgetLine::findOrFail($d['to_budget_line_id']);if($from->grant_agreement_id!==$to->grant_agreement_id||$from->project_id!==$to->project_id||$from->currency_id!==$to->currency_id)throw ValidationException::withMessages(['to_budget_line_id'=>'Realokasi hanya boleh antar budget line dalam grant, project, dan currency yang sama.']); return response()->json(['success'=>true,'data'=>BudgetReallocation::create([...$d,'project_id'=>$d['project_id']??$from->project_id,'reference'=>'BR-'.now()->format('YmdHis'), 'created_by'=>$r->user()->id])],201);} public function submit(Request $r,BudgetReallocation $budgetReallocation){if($budgetReallocation->status!=='draft')throw ValidationException::withMessages(['status'=>'Only draft may be submitted.']);$budgetReallocation->update(['status'=>'submitted','submitted_by'=>$r->user()->id,'submitted_at'=>now()]);return response()->json(['success'=>true,'data'=>$budgetReallocation]);} public function approve(Request $r,BudgetReallocation $budgetReallocation,BudgetMonitoringService $budget){if($budgetReallocation->status!=='submitted')throw ValidationException::withMessages(['status'=>'Only submitted may be approved.']);$available=$budget->validate($budgetReallocation->from_budget_line_id,$budgetReallocation->amount);if(!$available['allowed'])throw ValidationException::withMessages(['amount'=>$available['message']]);DB::transaction(function()use($budgetReallocation,$r){$from=$budgetReallocation->fromLine()->lockForUpdate()->first();$to=$budgetReallocation->toLine()->lockForUpdate()->first();$from->total_amount=round((float)$from->total_amount-(float)$budgetReallocation->amount,2);$from->base_amount=round($from->total_amount*max((float)($from->exchange_rate?:1),0.000001),2);$from->save();$to->total_amount=round((float)$to->total_amount+(float)$budgetReallocation->amount,2);$to->base_amount=round($to->total_amount*max((float)($to->exchange_rate?:1),0.000001),2);$to->save();$budgetReallocation->update(['status'=>'applied','approved_by'=>$r->user()->id,'approved_at'=>now(),'decision_notes'=>$r->input('notes')]);});return response()->json(['success'=>true,'data'=>$budgetReallocation->fresh()]);} }
